INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Abigail Vásquez is a Dominican Christian singer and worship leader celebrated for her passionate vocal interpretations and healing-centered devotional music.","type":"text"}]},{"type":"paragraph","content":[{"text":"Origins and musical calling","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Born in Santo Domingo, Vásquez grew up immersed in the spiritual life and choral assemblies of the local evangelical church. Her early musical development centered on congregational worship, fostering a heartfelt style focused on divine grace and biblical promise.","type":"text"}]},{"type":"paragraph","content":[{"text":"Impact of «Te Tocaré» and discography","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Vásquez achieved international reach with the release of «Te Tocaré», an emotive worship ballad inspired by biblical accounts of faith and physical restoration. The song reached hundreds of thousands of listeners across digital streaming services and YouTube, solidifying her voice within modern Christian hymnody alongside titles like «Tu Gracia» and «Rindo Mi Corazón».","type":"text"}]},{"type":"paragraph","content":[{"text":"Live ministry and spiritual vision","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Her performances blend contemporary acoustic praise with passionate vocal climaxes designed for congregational engagement. Through live conferences, media outreach, and worship recordings, Vásquez continually directs audiences toward deeper spiritual communion.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'abigail-vasquez';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Abigail Vásquez es una cantante y salmista cristiana dominicana distinguida por su capacidad interpretativa y su repertorio de alabanza congregacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Orígenes y vocación ministerial","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nacida en Santo Domingo, creció vinculada a la liturgia comunitaria y a los ministerios corales de las iglesias cristianas de la capital. Desde sus primeros años consagró su voz al servicio eclesiástico, perfilando un estilo devocional de marcado arraigo escritural.","type":"text"}]},{"type":"paragraph","content":[{"text":"Trascendencia de «Te Tocaré» y discografía","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cobró notoriedad en el circuito de música de fe con el lanzamiento de «Te Tocaré», cántico fundamentado en los pasajes bíblicos de sanidad y fe perseverante que acumuló cientos de miles de reproducciones en plataformas digitales. Su discografía incluye además temas destacados como «Tu Gracia» y «Rindo Mi Corazón».","type":"text"}]},{"type":"paragraph","content":[{"text":"Ministerio en vivo y visión espiritual","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"La instrumentación de sus canciones combina elementos de la balada acústica y el pop contemporáneo con una sobria entrega vocal. Abigail Vásquez participa activamente en jornadas de adoración, campañas evangelísticas y retiros espirituales en toda la geografía dominicana.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'abigail-vasquez';
UPDATE artists SET bio_en = 'Abigail Vásquez is a Dominican Christian singer and worship leader celebrated for her passionate vocal interpretations and healing-centered devotional music.

**Origins and musical calling**

Born in Santo Domingo, Vásquez grew up immersed in the spiritual life and choral assemblies of the local evangelical church. Her early musical development centered on congregational worship, fostering a heartfelt style focused on divine grace and biblical promise.

**Impact of «Te Tocaré» and discography**

Vásquez achieved international reach with the release of «Te Tocaré», an emotive worship ballad inspired by biblical accounts of faith and physical restoration. The song reached hundreds of thousands of listeners across digital streaming services and YouTube, solidifying her voice within modern Christian hymnody alongside titles like «Tu Gracia» and «Rindo Mi Corazón».

**Live ministry and spiritual vision**

Her performances blend contemporary acoustic praise with passionate vocal climaxes designed for congregational engagement. Through live conferences, media outreach, and worship recordings, Vásquez continually directs audiences toward deeper spiritual communion.', bio_es = 'Abigail Vásquez es una cantante y salmista cristiana dominicana distinguida por su capacidad interpretativa y su repertorio de alabanza congregacional.

**Orígenes y vocación ministerial**

Nacida en Santo Domingo, creció vinculada a la liturgia comunitaria y a los ministerios corales de las iglesias cristianas de la capital. Desde sus primeros años consagró su voz al servicio eclesiástico, perfilando un estilo devocional de marcado arraigo escritural.

**Trascendencia de «Te Tocaré» y discografía**

Cobró notoriedad en el circuito de música de fe con el lanzamiento de «Te Tocaré», cántico fundamentado en los pasajes bíblicos de sanidad y fe perseverante que acumuló cientos de miles de reproducciones en plataformas digitales. Su discografía incluye además temas destacados como «Tu Gracia» y «Rindo Mi Corazón».

**Ministerio en vivo y visión espiritual**

La instrumentación de sus canciones combina elementos de la balada acústica y el pop contemporáneo con una sobria entrega vocal. Abigail Vásquez participa activamente en jornadas de adoración, campañas evangelísticas y retiros espirituales en toda la geografía dominicana.' WHERE slug = 'abigail-vasquez';

