SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Dianette (Dianette Méndez) is a celebrated Dominican Christian singer-songwriter, pianist, and worship leader known for her emotive, piano-led congregational praise.","type":"text"}]},{"type":"paragraph","content":[{"text":"Musical beginnings and piano formation","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Born in Santo Domingo, Dianette developed both her vocal gifts and piano musicianship from childhood in evangelical church services. Cultivating a deep intimacy in personal and congregational prayer, she anchored her musical ministry around acoustic piano accompaniment and heartfelt lyricism.","type":"text"}]},{"type":"paragraph","content":[{"text":"Breakthrough anthems and Desde Adentro","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She attained national and international prominence with devotionally focused singles including «La Samaritana», «Adórale Ya Viene El Rey», and «Quien Te Ve Adorando». Her project *Desde Adentro*, recorded in intimate acoustic sessions, highlighted her vocal expressiveness and earned millions of streams on digital networks.","type":"text"}]},{"type":"paragraph","content":[{"text":"Worship style and international ministry","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Characterized by stripped-back piano melodies and themes of spiritual endurance, repentance, and unconditional trust in God, Dianette ministers frequently across church conferences and conventions in the Dominican Republic and abroad, guiding believers into heartfelt worship.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'dianette';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Dianette (Dianette Méndez) es una destacada cantautora, pianista y líder de alabanza cristiana dominicana reconocida por su estilo de adoración íntima al piano y su unción interpretativa.","type":"text"}]},{"type":"paragraph","content":[{"text":"Primeros años y formación al piano","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Nacida en Santo Domingo, creció vinculada a los altares evangélicos, donde aprendió a interpretar el piano acústico y a armonizar su canto en cultos congregacionales. Su apego al instrumento convirtió al piano en el eje de sus composiciones y ministraciones devocionales.","type":"text"}]},{"type":"paragraph","content":[{"text":"Canciones emblemáticas y Desde Adentro","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cobró amplio reconocimiento con piezas devocionales de profundo testimonio como «La Samaritana», «Adórale Ya Viene El Rey» y «Quien Te Ve Adorando». Su serie y proyecto *Desde Adentro*, concebido en formato de adoración espontánea y arreglos acústicos, resonó ampliamente en iglesias hispanoamericanas y acumuló millones de visualizaciones en canales digitales.","type":"text"}]},{"type":"paragraph","content":[{"text":"Estilo y ministerio internacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su propuesta enfatiza la sencillez armónica, el mensaje de edificación en momentos de prueba y la rendición ante Dios. Dianette participa regularmente en conferencias cristianas y congresos de mujeres a nivel nacional e internacional, consolidándose como una de las salmistas más queridas de la República Dominicana.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'dianette';
UPDATE artists SET bio_en = 'Dianette (Dianette Méndez) is a celebrated Dominican Christian singer-songwriter, pianist, and worship leader known for her emotive, piano-led congregational praise.

**Musical beginnings and piano formation**

Born in Santo Domingo, Dianette developed both her vocal gifts and piano musicianship from childhood in evangelical church services. Cultivating a deep intimacy in personal and congregational prayer, she anchored her musical ministry around acoustic piano accompaniment and heartfelt lyricism.

**Breakthrough anthems and Desde Adentro**

She attained national and international prominence with devotionally focused singles including «La Samaritana», «Adórale Ya Viene El Rey», and «Quien Te Ve Adorando». Her project *Desde Adentro*, recorded in intimate acoustic sessions, highlighted her vocal expressiveness and earned millions of streams on digital networks.

**Worship style and international ministry**

Characterized by stripped-back piano melodies and themes of spiritual endurance, repentance, and unconditional trust in God, Dianette ministers frequently across church conferences and conventions in the Dominican Republic and abroad, guiding believers into heartfelt worship.', bio_es = 'Dianette (Dianette Méndez) es una destacada cantautora, pianista y líder de alabanza cristiana dominicana reconocida por su estilo de adoración íntima al piano y su unción interpretativa.

**Primeros años y formación al piano**

Nacida en Santo Domingo, creció vinculada a los altares evangélicos, donde aprendió a interpretar el piano acústico y a armonizar su canto en cultos congregacionales. Su apego al instrumento convirtió al piano en el eje de sus composiciones y ministraciones devocionales.

**Canciones emblemáticas y Desde Adentro**

Cobró amplio reconocimiento con piezas devocionales de profundo testimonio como «La Samaritana», «Adórale Ya Viene El Rey» y «Quien Te Ve Adorando». Su serie y proyecto *Desde Adentro*, concebido en formato de adoración espontánea y arreglos acústicos, resonó ampliamente en iglesias hispanoamericanas y acumuló millones de visualizaciones en canales digitales.

**Estilo y ministerio internacional**

Su propuesta enfatiza la sencillez armónica, el mensaje de edificación en momentos de prueba y la rendición ante Dios. Dianette participa regularmente en conferencias cristianas y congresos de mujeres a nivel nacional e internacional, consolidándose como una de las salmistas más queridas de la República Dominicana.' WHERE slug = 'dianette';

