INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Gerkin Mateo is a Dominican contemporary Christian worship singer, songwriter, and recording artist from Santo Domingo, Dominican Republic. Widely recognized as one of the most vibrant vocalists of the new generation of Latin gospel and congregational worship, he is noted for his resonant tenor range, profound emotive conviction, and a stylistic versatility that bridges acoustic Latin pop, melodic Caribbean rhythms, and prophetic praise.","type":"text"}]},{"type":"paragraph","content":[{"text":"National breakthrough on The Voice Dominicana (2022)","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Mateo gained nationwide acclaim in 2022 as a standout competitor on the second season of the televised singing competition ","type":"text"},{"text":"The Voice Dominicana","type":"text","marks":[{"type":"italic"}]},{"text":". During the Blind Auditions, his soulful acoustic reinterpretation of «Bachata Rosa» by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"4f1b8a3a-f229-4773-a66f-cdbbab64bb0c"}},{"text":" prompted immediate praise and a fierce competition between coaches. He joined the team of merengue superstar ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"1a6d82e1-14ed-4448-b8bc-19666dfce138"}},{"text":" (Team Eddy), where national media characterized him as «un adorador cristiano con mucho flow» (a Christian worship artist with extraordinary flow). He subsequently triumphed in the Battles phase performing Guerra''s «Como Abeja al Panal» alongside Damilca Reinoso, before delivering a moving performance of «En Todo Tiempo» in the Knockouts round.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recording career and collaborative ministry","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Building upon his television momentum, Gerkin Mateo firmly anchored his musical career within contemporary Christian worship. He established high-impact musical partnerships with top-tier Dominican gospel collectives, most notably collaborating with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace","occurrenceId":"ef53746a-3df0-46b7-8574-02ac383e5778"}},{"text":" on the studio single «La Mano de Dios» as well as the live congregational medley «Mi Plenitud + Volvamos al Inicio». His solo catalog features acclaimed congregational anthems including «¿Quién Es Él?», «Alábale», «La Cisterna», and his signature track «El Hebreo» (recorded both in full-band studio arrangements and in an intimate live acoustic setting with Andri Corporán). He has also recorded collaborative worship songs such as «Amor Sin Condición» with Jhon Bautista.","type":"text"}]},{"type":"paragraph","content":[{"text":"Artistic identity and spiritual mission","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Operating under his ministerial maxim «Hasta mi último aliento» (Until my last breath), Mateo combines authentic congregational adoration with contemporary production values. With an engaged digital following exceeding 78,000 on Instagram and millions of collective views on YouTube, he stands as a vital and modernizing voice in the Dominican Republic''s sacred music landscape.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'gerkin-mateo';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Gerkin Mateo es un cantante, compositor y adorador contemporáneo dominicano oriundo de Santo Domingo, República Dominicana. Reconocido como una de las voces jóvenes más notables y prometedoras del movimiento de alabanza y música cristiana en el país, destaca por una tesitura de tenor brillante, una honda expresividad interpretativa y una propuesta artística que fusiona el pop acústico, matices caribeños de bachata y la adoración profética de gran escala congregacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Consagración nacional en The Voice Dominicana (2022)","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su proyección artística cobró notoriedad masiva en 2022 tras su participación en la segunda temporada del certamen televisivo ","type":"text"},{"text":"The Voice Dominicana","type":"text","marks":[{"type":"italic"}]},{"text":". Durante las Audiciones a Ciegas, cautivó a los entrenadores y al público con una sentida interpretación acústica del clásico «Bachata Rosa» del maestro ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"69f3b09c-ce17-4674-a01c-b3d1fd10d846"}},{"text":", integrándose al equipo del afamado merenguero ","type":"text"},{"type":"artistReference","attrs":{"artistId":"ae3c0afb-0e0a-4506-bbe6-a59c3c68bb1e","displayText":"Eddy Herrera","occurrenceId":"fd976a43-b467-4059-94a6-99cb20f41424"}},{"text":" (Team Eddy). La prensa y la crítica especializada lo destacaron de inmediato como «un adorador cristiano con mucho flow», elogiando su soltura melódica y afinación impecable. En la fase de Las Batallas resultó vencedor tras interpretar a dúo «Como Abeja al Panal» junto a Damilca Reinoso, avanzando con honores hasta los Knockouts, donde defendió el tema «En Todo Tiempo».","type":"text"}]},{"type":"paragraph","content":[{"text":"Carrera discográfica y colaboraciones ministeriales","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Tras su paso por la televisión, Mateo consolidó su carrera en los altares y en el circuito discográfico cristiano internacional. Estableció importantes alianzas musicales con referentes del género, destacando su colaboración con el reconocido colectivo ","type":"text"},{"type":"artistReference","attrs":{"artistId":"43a14bc5-52fd-43df-9bd9-15f3b11dcf3b","displayText":"Grupo Grace","occurrenceId":"e707cecb-4f2c-465d-9bb6-9e7cab6d99f5"}},{"text":" en el sencillo «La Mano de Dios» y en la versión en vivo de «Mi Plenitud + Volvamos al Inicio». Su repertorio solista incluye himnos de gran calado congregacional como «¿Quién Es Él?», «Alábale», «La Cisterna» y su tema insignia «El Hebreo», grabado en estudio y en formato acústico en vivo con Andri Corporán. Asimismo, ha colaborado en sencillos como «Amor Sin Condición» junto a Jhon Bautista.","type":"text"}]},{"type":"paragraph","content":[{"text":"Identidad artística y ministerio","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Impulsado por el lema ministerial «Hasta mi último aliento», Gerkin Mateo conjuga la pureza de la alabanza devocional con arreglos musicales modernos. Con una sólida comunidad de más de 78,000 seguidores en Instagram y una constante presencia en congresos juveniles y templos de la región, se erige como una figura representativa del renacer de la música cristiana en la República Dominicana.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'gerkin-mateo';
UPDATE artists SET bio_en = 'Gerkin Mateo is a Dominican contemporary Christian worship singer, songwriter, and recording artist from Santo Domingo, Dominican Republic. Widely recognized as one of the most vibrant vocalists of the new generation of Latin gospel and congregational worship, he is noted for his resonant tenor range, profound emotive conviction, and a stylistic versatility that bridges acoustic Latin pop, melodic Caribbean rhythms, and prophetic praise.

**National breakthrough on The Voice Dominicana (2022)**
Mateo gained nationwide acclaim in 2022 as a standout competitor on the second season of the televised singing competition *The Voice Dominicana*. During the Blind Auditions, his soulful acoustic reinterpretation of «Bachata Rosa» by Juan Luis Guerra prompted immediate praise and a fierce competition between coaches. He joined the team of merengue superstar Eddy Herrera (Team Eddy), where national media characterized him as «un adorador cristiano con mucho flow» (a Christian worship artist with extraordinary flow). He subsequently triumphed in the Battles phase performing Guerra''s «Como Abeja al Panal» alongside Damilca Reinoso, before delivering a moving performance of «En Todo Tiempo» in the Knockouts round.

**Recording career and collaborative ministry**
Building upon his television momentum, Gerkin Mateo firmly anchored his musical career within contemporary Christian worship. He established high-impact musical partnerships with top-tier Dominican gospel collectives, most notably collaborating with Grupo Grace on the studio single «La Mano de Dios» as well as the live congregational medley «Mi Plenitud + Volvamos al Inicio». His solo catalog features acclaimed congregational anthems including «¿Quién Es Él?», «Alábale», «La Cisterna», and his signature track «El Hebreo» (recorded both in full-band studio arrangements and in an intimate live acoustic setting with Andri Corporán). He has also recorded collaborative worship songs such as «Amor Sin Condición» with Jhon Bautista.

**Artistic identity and spiritual mission**
Operating under his ministerial maxim «Hasta mi último aliento» (Until my last breath), Mateo combines authentic congregational adoration with contemporary production values. With an engaged digital following exceeding 78,000 on Instagram and millions of collective views on YouTube, he stands as a vital and modernizing voice in the Dominican Republic''s sacred music landscape.', bio_es = 'Gerkin Mateo es un cantante, compositor y adorador contemporáneo dominicano oriundo de Santo Domingo, República Dominicana. Reconocido como una de las voces jóvenes más notables y prometedoras del movimiento de alabanza y música cristiana en el país, destaca por una tesitura de tenor brillante, una honda expresividad interpretativa y una propuesta artística que fusiona el pop acústico, matices caribeños de bachata y la adoración profética de gran escala congregacional.

**Consagración nacional en The Voice Dominicana (2022)**
Su proyección artística cobró notoriedad masiva en 2022 tras su participación en la segunda temporada del certamen televisivo *The Voice Dominicana*. Durante las Audiciones a Ciegas, cautivó a los entrenadores y al público con una sentida interpretación acústica del clásico «Bachata Rosa» del maestro Juan Luis Guerra, integrándose al equipo del afamado merenguero Eddy Herrera (Team Eddy). La prensa y la crítica especializada lo destacaron de inmediato como «un adorador cristiano con mucho flow», elogiando su soltura melódica y afinación impecable. En la fase de Las Batallas resultó vencedor tras interpretar a dúo «Como Abeja al Panal» junto a Damilca Reinoso, avanzando con honores hasta los Knockouts, donde defendió el tema «En Todo Tiempo».

**Carrera discográfica y colaboraciones ministeriales**
Tras su paso por la televisión, Mateo consolidó su carrera en los altares y en el circuito discográfico cristiano internacional. Estableció importantes alianzas musicales con referentes del género, destacando su colaboración con el reconocido colectivo Grupo Grace en el sencillo «La Mano de Dios» y en la versión en vivo de «Mi Plenitud + Volvamos al Inicio». Su repertorio solista incluye himnos de gran calado congregacional como «¿Quién Es Él?», «Alábale», «La Cisterna» y su tema insignia «El Hebreo», grabado en estudio y en formato acústico en vivo con Andri Corporán. Asimismo, ha colaborado en sencillos como «Amor Sin Condición» junto a Jhon Bautista.

**Identidad artística y ministerio**
Impulsado por el lema ministerial «Hasta mi último aliento», Gerkin Mateo conjuga la pureza de la alabanza devocional con arreglos musicales modernos. Con una sólida comunidad de más de 78,000 seguidores en Instagram y una constante presencia en congresos juveniles y templos de la región, se erige como una figura representativa del renacer de la música cristiana en la República Dominicana.' WHERE slug = 'gerkin-mateo';

