SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Las Gemelas de la Bachata es un dúo emergente dominicano de bachata formado por dos hermanas gemelas que publican sus canciones desde 2022 en su propio canal de YouTube. Son conocidas sobre todo por «Quiero Ser Como Tú», colaboración con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"4f331050-2568-42a4-a73b-7f9a731f1df4","displayText":"Dalvin la Melodía","occurrenceId":"adfbea86-d88e-4fc1-b392-45d2de83b03e"}},{"text":" lanzada en enero de 2026 que supera las 85 000 vistas.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su catálogo hasta ahora incluye además «Masoquista» (octubre de 2025), «Me Voy Emborrachar» (marzo de 2026), «Te Recordaré», homenaje a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"60e38a9b-92cd-44ad-807a-70a775ef5aa4"}},{"text":" (septiembre de 2026), y «Cuiden Los Niños» (septiembre de 2026).","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'las-gemelas-de-la-bachata';
UPDATE artists SET bio_en = 'Las Gemelas de la Bachata is an emerging Dominican bachata duo of twin sisters who have released their songs through their own YouTube channel since 2022. They are best known for «Quiero Ser Como Tú», a collaboration with Dalvin la Melodía released in January 2026 that has passed 85,000 views.

**Legacy**

Their catalogue so far also includes «Masoquista» (October 2025), «Me Voy Emborrachar» (March 2026), «Te Recordaré», a tribute to Rubby Pérez (September 2026), and «Cuiden Los Niños» (September 2026).', bio_es = 'Las Gemelas de la Bachata es un dúo emergente dominicano de bachata formado por dos hermanas gemelas que publican sus canciones desde 2022 en su propio canal de YouTube. Son conocidas sobre todo por «Quiero Ser Como Tú», colaboración con Dalvin la Melodía lanzada en enero de 2026 que supera las 85 000 vistas.

**Legado**

Su catálogo hasta ahora incluye además «Masoquista» (octubre de 2025), «Me Voy Emborrachar» (marzo de 2026), «Te Recordaré», homenaje a Rubby Pérez (septiembre de 2026), y «Cuiden Los Niños» (septiembre de 2026).' WHERE slug = 'las-gemelas-de-la-bachata';

