-4f1b-92cf-f3801ff1b589"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"081c1484-bf1c-4b11-ba01-d68446b7b111","displayText":"Anthony Ríos","occurrenceId":"4e32008d-feee-4b9e-82a7-8058c957aabe"}},{"text":". He told Listín Diario that, wherever his career leads, he will not “divorce” himself from emerging artists and piano-bar singers.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'nacho-estrella';
