ation","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He is not the only one. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fc762d4-96b8-4ecf-aca8-fdf52936658e","displayText":"Toño Rosario","occurrenceId":"4dfea37c-91e1-45f1-a58d-841d4555cb2a"}},{"text":"’s son Checho Rosario is doing the same thing from the other branch of the family, and the two of them get compared constantly — two grandsons of the same dynasty, two styles, the same job of keeping it going.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'rafely-rosario';
