INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Anthony Santos, known as Romeo Santos, is a bachata singer, composer and producer born in the Bronx on 21 July 1981 to a Dominican father and a Puerto Rican mother. As lead voice and songwriter of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"659a3fd8-511f-4fbf-8f02-4515db900bb1"}},{"text":" he rebuilt bachata around hip hop and R&B and carried it onto European charts; as a soloist he became the first Latin artist to headline Yankee Stadium and MetLife Stadium. He is widely called the King of Bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Tinellers","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The group formed in the Bronx in the early 1990s around the brothers Lenny and Max Santos, who recruited Anthony and his cousin ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8dcfc4e1-9af4-4378-9e19-52573af429a7","displayText":"Henry Santos","occurrenceId":"6b956c32-c08b-47b7-b03c-d4331055c941"}},{"text":". They called themselves «Los Tinellers», the word teenagers spelled as it sounds in Spanish, and their «Trampa de Amor» (1996) sold almost nothing. The manager Julio César García renamed them ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"dbdcbe1d-fc67-4440-a32c-951e96ac06a4"}},{"text":", and in 1998 the group signed to «Premium Latin Music».","type":"text"}]},{"type":"paragraph","content":[{"text":"Anthony took the stage name Romeo partly because his own was already taken: ","type":"text"},{"type":"artistReference","attrs":{"artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos","occurrenceId":"21cda1f1-4ffd-4f02-a3bf-d09721c0b773"}},{"text":" had been recording as Anthony Santos since the late 1980s.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Obsesión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Generation Next» (1999) reworked «Cuándo Volverás» into the group''s debut single, but the turn came with «We Broke the Rules» (2002) and «Obsesión», a duet with Judy Santos. In the United States it reached only number 32 on the tropical chart; in Europe it went to number one in seven countries and held the top of the Italian chart for sixteen consecutive weeks — a bachata sung in Spanish, on Italian radio, by four men from the Bronx.","type":"text"}]},{"type":"paragraph","content":[{"text":"What they had changed was the arrangement: Lenny Santos ran the requinto through wah, phaser and harmonizer, Max Santos played bass with slaps and rock riffs, and the lyrics moved between Spanish and English. The sound was named bachata urbana, and most of the genre has been written in it since.","type":"text"}]},{"type":"paragraph","content":[{"text":"The decade of Aventura","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Love & Hate» (2003) produced «Hermanita». «God''s Project» (2005), the first album distributed by «Sony Music Latin», carried «Un Beso» and «Ella y Yo», a duet with Don Omar that pulled a reggaetón audience into bachata. «K.O.B. Live» (2006) gave «Mi Corazoncito», and «The Last» (2009) opened with «Por un Segundo», the group''s first number one on the Hot Latin Songs chart.","type":"text"}]},{"type":"paragraph","content":[{"text":"In 2007 ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"50c3d861-0d53-4352-a282-c6069eff5c8f"}},{"text":" became the first bachata act to sell out Madison Square Garden. By 2011 it had sold more than 1.7 million records in the United States on five studio albums in a decade, and Santos held twelve ASCAP awards for songs he had written for it. The group separated that year.","type":"text"}]},{"type":"paragraph","content":[{"text":"The «Fórmula» trilogy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Santos signed with «Sony Music Latin» in 2011 and released «Fórmula, Vol. 1» that November; «Promise», with Usher, is certified diamond. «Fórmula, Vol. 2» (2014) is the commercial peak: «Propuesta Indecente» spent 125 weeks on the Hot Latin Songs chart and passed two billion views on YouTube, and «Odio» was the first record on which Drake sang in Spanish. «Golden» (2017) followed with «Héroe Favorito» and «Imitadora».","type":"text"}]},{"type":"paragraph","content":[{"text":"«Fórmula, Vol. 3» (2022) closed the trilogy, with «Sin Fin» alongside Justin Timberlake, «El Pañuelo» with Rosalía, and «15,500 Noches», a merengue recorded with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"556e95ab-b6e9-4e71-bd81-2556006ea3ff"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cff70c92-8632-4c66-b5a0-81622c8128b0","displayText":"Rubby Pérez","occurrenceId":"cf7ebc97-2b1d-4832-ac6c-57b09220ba3b"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6fc762d4-96b8-4ecf-aca8-fdf52936658e","displayText":"Toño Rosario","occurrenceId":"66f7d9c7-d793-482a-8949-318c9dd0d7c4"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02f23257-1cf6-4a4c-8df1-1f9aa630a2c3","displayText":"Ramón Orlando & Orquesta Internacional","occurrenceId":"c53b1b20-3afb-4df2-ae20-60b75cca2336"}},{"text":". It won the 2023 Latin Grammy for best merengue and/or bachata album, in a tie with «A Mi Manera» by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"059a9e99-5d11-433e-97b9-9c35e57908f1","displayText":"Sergio Vargas","occurrenceId":"7f414f77-27fc-4537-a2cf-c570139d0784"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"«Utopía»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"«Utopía» (2019) is the record that matters most to the Dominican tradition. Santos wrote twelve songs in the old style and recorded each as a duet with a bachatero of the generation before his, most of whom had never had a hit on United States radio:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Canalla» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8be8c38c-e6a5-4e0d-83d1-8c8d20813ce6","displayText":"El Chaval de la Bachata","occurrenceId":"1a78d3d4-e69c-4e34-8c54-24d4a1bd5869"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Payasos» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3dd83e6b-2058-4d04-ac68-38e11d9348a9","displayText":"Frank Reyes","occurrenceId":"ac430db8-79e2-43d8-8d29-a7d3a5515eb9"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«La Demanda» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"96e69c00-dbb0-4cb4-ab48-ea46be9c4591","displayText":"Raulín Rodríguez","occurrenceId":"86de34dc-1f7e-490a-8433-83cca94ce54b"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Millonario» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e566c763-02c1-4f96-8a82-edbba9fc0bb2","displayText":"Elvis Martínez","occurrenceId":"15315300-a36b-42e6-ae28-6510090cda4d"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«El Beso Que No Le Di» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2a4813af-a826-410e-9475-b2bd1474b234","displayText":"Kiko Rodríguez","occurrenceId":"c2962476-966b-43b2-82ed-ea8779fd2850"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Ileso» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"97aba7a6-2428-4540-8ddd-79ea8c487e36","displayText":"Teodoro Reyes","occurrenceId":"294358ac-05e0-4660-8516-156dc0eba6ab"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Amor Enterrado» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"aec32df5-cc5a-43c2-ac33-02bc8caa1cf5","displayText":"Joe Veras","occurrenceId":"f713584d-f223-4007-ac85-aa3f0e0c513b"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Me Quedo» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"a77079ce-351a-4eb5-baef-de02dc1b62ce","displayText":"Zacarías Ferreira","occurrenceId":"fba5cb42-d057-4ba7-ae68-7b5736403a77"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Los Últimos» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0760875d-6b6f-4a48-8aed-6e57934d1baa","displayText":"Luis Vargas","occurrenceId":"e1f69211-7c0a-446a-abba-fec1fde86280"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Años Luz» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"7c732c88-a17c-4234-8033-d7605e0a9310","displayText":"Monchy & Alexandra","occurrenceId":"90d11d51-b65a-4160-a642-c4d4fe396b5e"}}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"«Bellas» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos","occurrenceId":"c16e9d3a-63e2-46d2-854e-26ea430852ba"}}]}]}]},{"type":"paragraph","content":[{"text":"The closing track, «Inmortal», reunited ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"08080335-00a4-4c1b-b6df-2f513e046484"}},{"text":" for the first time in a decade. The album topped the Top Latin Albums chart and is certified eleven times platinum in the Latin field.","type":"text"}]},{"type":"paragraph","content":[{"text":"The stadiums","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He sold out two consecutive nights at Yankee Stadium in July 2014, the first Latin solo artist to headline it, and on 21 September 2019 filled MetLife Stadium with some sixty thousand people, again the first, releasing the night as «Utopía Live from MetLife Stadium». «Fórmula, Vol. 3: La Gira» ran eighty-eight shows through 2023.","type":"text"}]},{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"37e0d22e-5fb2-4d72-b8b2-f448e30b1a21"}},{"text":" reunited for a farewell tour, «Cerrando Ciclos», which closed on 5 January 2025 at the Estadio Olímpico Félix Sánchez in Santo Domingo before more than fifty thousand people, the last of four sold-out nights in the country. In November 2025 Santos released «Better Late Than Never», a surprise joint album with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9c02d1a1-952e-4855-9b60-c0266236378d","displayText":"Prince Royce","occurrenceId":"1611aefd-b2a1-48ea-aef8-12c4c1e6017a"}},{"text":", and the two opened the «Mejor Tarde Que Nunca» tour in April 2026.","type":"text"}]},{"type":"paragraph","content":[{"text":"The songwriter","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Santos wrote almost the whole ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"fd92795e-3cf1-4641-b3b1-34ac29677142"}},{"text":" catalogue — the group recorded one cover in its career — and has written for others throughout. «No, No, No», written and sung with Thalía, won pop song of the year at «Premios Lo Nuestro» in 2007. For ","type":"text"},{"type":"artistReference","attrs":{"artistId":"dee014d6-cb3c-4abb-9262-165538277a0d","displayText":"Héctor Acosta “El Torito”","occurrenceId":"fa6d71f9-c9f2-4ef8-86c4-0d82d9c6fafa"}},{"text":" he wrote «Me voy», a bachata rewrite of an ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"61c5354f-c807-4a69-8e9a-09e301d8d545"}},{"text":" merengue, and «Amorcito enfermito», a number one on the Tropical Airplay chart in 2016; in 2020 he cut a duet version of «Nuestro Amor» with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6c3e0d74-23b7-4d80-969f-9d5319ee5127","displayText":"Alex Bueno","occurrenceId":"432ebd06-d3bd-4d68-8ba7-cbeb8b75712d"}},{"text":". He was named songwriter of the year at the «Billboard» Latin Music Awards in 2007 and from 2014 to 2016, and producer of the year in 2014 and 2015.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"3a7c19e8-5d24-4f06-b8e1-9c4a70f2d5b3","displayText":"Aventura","occurrenceId":"1aaff5fa-138a-48f4-95d6-7e5d0ae2c5b5"}},{"text":" is the point at which bachata stopped being a Dominican genre exported abroad and became one written abroad and sold back home. Santos holds a Latin Grammy, three «Billboard» Music Awards and nineteen «Premios Lo Nuestro», which gave him its excellence award in 2017, and ACROARTE named him El Gran Soberano in 2021 — its highest distinction, for a Dominican career, given to a man born in New York.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Utopía» is the clearest statement of what he does with that position: having become the most commercially successful bachatero in the genre''s history, he spent an album handing the microphone back to ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0760875d-6b6f-4a48-8aed-6e57934d1baa","displayText":"Luis Vargas","occurrenceId":"44336eec-06b4-409f-aea3-dbb6cd26bc94"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"28a3745e-90d6-45cd-b8bd-798028f8deb8","displayText":"Antony Santos","occurrenceId":"5ff0e13e-a7aa-4438-b533-af44da988ac3"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"96e69c00-dbb0-4cb4-ab48-ea46be9c4591","displayText":"Raulín Rodríguez","occurrenceId":"df601717-95a9-4fce-a3e6-9a82e26496bf"}},{"text":" and the others who had made the form he rebuilt, and put them on charts they had never reached.","type":"text"}]}]}'::jsonb, 'published', id, 3 FROM artists WHERE slug = 'romeo-santos';
