SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"World Worship is an acclaimed Dominican contemporary worship collective founded in Santo Domingo by directors Jamilet González and Jireh Heredia, celebrated for massive congregational productions and international church anthems.","type":"text"}]},{"type":"paragraph","content":[{"text":"A church-centered collective movement","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Born as an interdenominational worship initiative bringing together talented musicians and vocalists from multiple Dominican congregations, World Worship emphasizes rich multicultural worship textures and high-level live audiovisual recordings. Their mission is to enrich and equip church music across the globe.","type":"text"}]},{"type":"paragraph","content":[{"text":"Live albums and viral anthems","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The collective has published widely distributed worship anthems including «Unción en el aire» (2024, featuring Cales Louima), «María (Yo elijo a Cristo)» (2023, with Grupo Grace), «Purifica» (2023), and «SABAOTH (Varón de Guerra)» (2025). Their live recordings on YouTube and streaming platforms have accumulated millions of views worldwide.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"World Worship stands at the forefront of the Caribbean worship movement, providing modern churches with powerful anthems that blend spiritual depth with contemporary musical excellence.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'world-worship';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"World Worship es un destacado colectivo dominicano de adoración contemporánea fundado en Santo Domingo bajo la dirección de Jamilet González y Jireh Heredia, reconocido por sus producciones corales en vivo y su repercusión internacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"Un movimiento de alabanza congregacional","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Concebido como una iniciativa intereclesial que congrega a instrumentistas y adoradores de diversas iglesias de la capital dominicana, World Worship se ha caracterizado por elevar los estándares de producción audiovisual y litúrgica de la alabanza hispana con el lema de añadir riqueza cultural a la música de la iglesia.","type":"text"}]},{"type":"paragraph","content":[{"text":"Producciones en vivo e himnos virales","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"El ministerio ha lanzado grabaciones de enorme difusión como «Unción en el aire» (2024, junto a Cales Louima), «María (Yo elijo a Cristo)» (2023, en colaboración con Grupo Grace), «Purifica» (2023) y «SABAOTH (Varón de Guerra)» (2025), sumando millones de reproducciones globales.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"World Worship representa la vitalidad de la alabanza comunitaria contemporánea en el Caribe, proveyendo al pueblo cristiano de herramientas musicales que inspiran reverencia y exaltación a Dios.","type":"text"}]}]}'::jsonb, 'published', id, 1 FROM artists WHERE slug = 'world-worship';
UPDATE artists SET bio_en = 'World Worship is an acclaimed Dominican contemporary worship collective founded in Santo Domingo by directors Jamilet González and Jireh Heredia, celebrated for massive congregational productions and international church anthems.

**A church-centered collective movement**

Born as an interdenominational worship initiative bringing together talented musicians and vocalists from multiple Dominican congregations, World Worship emphasizes rich multicultural worship textures and high-level live audiovisual recordings. Their mission is to enrich and equip church music across the globe.

**Live albums and viral anthems**

The collective has published widely distributed worship anthems including «Unción en el aire» (2024, featuring Cales Louima), «María (Yo elijo a Cristo)» (2023, with Grupo Grace), «Purifica» (2023), and «SABAOTH (Varón de Guerra)» (2025). Their live recordings on YouTube and streaming platforms have accumulated millions of views worldwide.

**Legacy**

World Worship stands at the forefront of the Caribbean worship movement, providing modern churches with powerful anthems that blend spiritual depth with contemporary musical excellence.', bio_es = 'World Worship es un destacado colectivo dominicano de adoración contemporánea fundado en Santo Domingo bajo la dirección de Jamilet González y Jireh Heredia, reconocido por sus producciones corales en vivo y su repercusión internacional.

**Un movimiento de alabanza congregacional**

Concebido como una iniciativa intereclesial que congrega a instrumentistas y adoradores de diversas iglesias de la capital dominicana, World Worship se ha caracterizado por elevar los estándares de producción audiovisual y litúrgica de la alabanza hispana con el lema de añadir riqueza cultural a la música de la iglesia.

**Producciones en vivo e himnos virales**

El ministerio ha lanzado grabaciones de enorme difusión como «Unción en el aire» (2024, junto a Cales Louima), «María (Yo elijo a Cristo)» (2023, en colaboración con Grupo Grace), «Purifica» (2023) y «SABAOTH (Varón de Guerra)» (2025), sumando millones de reproducciones globales.

**Legado**

World Worship representa la vitalidad de la alabanza comunitaria contemporánea en el Caribe, proveyendo al pueblo cristiano de herramientas musicales que inspiran reverencia y exaltación a Dios.' WHERE slug = 'world-worship';

