ccurrenceId":"2c9c5896-69e9-4a4c-b710-05329c9d6a06"}},{"text":" on Que Se Abran Los Cielos, and has recorded with Arisa and Artelis through Frilop Music. In 2024 she appeared in the Dominican film Justo a Tiempo.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recognition","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Yamilka has been recognised repeatedly at Premios El Galardón, the principal awards for Spanish-language Christian music, in the Female Artist of the Year category across 2018, 2019, 2021, 2022 and 2024, having first been nominated as a breakthrough artist in 2015.","type":"text"}]},{"type":"paragraph","content":[{"text":"Her trajectory is a common one in Dominican worship and an easy one to miss from outside: years of uncredited work behind established acts, then a solo career built on the relationships and the craft that work produced. The Barak connection did not simply give her exposure — it gave her a producer, and that partnership has shaped everything she has released.","type":"text"}]}]}'::jsonb, 'published', id, 4 FROM artists WHERE slug = 'yamilka';
