SELECT 'artist_biography', 'en', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Yammy —born Carmen Jamilka Peña Vargas in Yamasá— is a Dominican bachata singer and songwriter based in New York. She first recorded as Yami Bonetti and came back in 2019 under the name Yammy.","type":"text"}]},{"type":"paragraph","content":[{"text":"Two stage names","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In June 2010 Diario Libre, drawing on a profile in the Miami paper El Nuevo Herald, introduced Yami Bonetti as a nineteen-year-old who had left «Las Caribeñas», where she stood in the second row of the chorus, because she no longer wanted to sing behind the lead voices. Her debut album opened with «No me queda más», a bachata take on a Selena song, and also carried Selena’s «Como una flor». By her own account she began at thirteen as a backing singer in a family group and later sang in local merengue and bachata bands; her single «Ya no vives en mí» took her on tours of the United States and the Caribbean, and after roughly four years she left the stage to concentrate on her private life. She returned in 2019 as Yammy.","type":"text"}]},{"type":"paragraph","content":[{"text":"Singles and collaborators","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Since then she has blended collaborations and urban and tropical touches into her bachata. Her singles include «Mala», «Te Superé», «Fuiste un Error», «La Gran Señora», «Tu Dama de Hierro» (2023), «Brindo X Mi Ex» (2024) and «Te Duele Verme Bien» (2025), the last written with Eddie Espinal. «El Gallo», recorded with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"550df3b5-6488-4aec-a476-a5d28d52ceea","displayText":"Bulin 47","occurrenceId":"bf2c1ca6-4fb2-43c6-a402-ebbbc1c3e8ef"}},{"text":", has passed 1.4 million views on YouTube. She names ","type":"text"},{"type":"artistReference","attrs":{"artistId":"aec32df5-cc5a-43c2-ac33-02bc8caa1cf5","displayText":"Joe Veras","occurrenceId":"acfda23d-81a9-4d4b-86ef-b58cf05c22b2"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6302aca6-2203-456f-ad96-6bd2f26ee9b3","displayText":"Luis Miguel del Amargue","occurrenceId":"3db238fa-8e3f-4b22-9a81-d6a9761dba71"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0b2e1a39-b265-42d6-95d5-85ad930eee84","displayText":"El Cherry Scom","occurrenceId":"03d3b389-aeea-489f-bdba-3c26254530e4"}},{"text":" among her collaborators, and has begun writing her own songs with producers and songwriters such as ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5cbc8f2b-cb68-4ebd-8006-6837be54bbe4","displayText":"Leo RD","occurrenceId":"cf7a0668-2efe-424e-818d-346ab0653c88"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"350e5535-5229-4d49-903e-a5de047e7723","displayText":"Cromo X","occurrenceId":"89f0e5bf-4116-418b-8373-324584b0fe6c"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"«Reina de Corazones»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Her song «Papi» is the second track on «Reina de Corazones», the third volume of the «Bchta Rising» compilation series from «BCHTA Records», released on 5 March 2026 with a group of other bachata artists that includes ","type":"text"},{"type":"artistReference","attrs":{"artistId":"eb79ffea-c981-4328-9d60-028caa180608","displayText":"Lady Laura","occurrenceId":"c12b292d-d4ca-4b3c-9971-d8d32effd35e"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She keeps releasing singles and performing in the United States, and in September 2025 gave a long interview to the YouTube channel Bacharlando.","type":"text"}]}]}'::jsonb, 'published', id, 2 FROM artists WHERE slug = 'yammy';
INSERT INTO editorial_documents (document_type, locale, schema_version, document, status, owner_artist_id, revision)
SELECT 'artist_biography', 'es', 1, '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Yammy —nacida Carmen Jamilka Peña Vargas en Yamasá— es cantante y compositora dominicana de bachata radicada en Nueva York. Grabó primero como Yami Bonetti y regresó en 2019 con el nombre de Yammy.","type":"text"}]},{"type":"paragraph","content":[{"text":"Dos nombres artísticos","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En junio de 2010 Diario Libre, apoyándose en un reportaje de El Nuevo Herald de Miami, presentó a Yami Bonetti como una joven de diecinueve años que había dejado «Las Caribeñas», donde cantaba en la segunda fila del coro, porque ya no quería estar detrás de las voces principales. Su álbum debut abría con «No me queda más», versión en bachata de una canción de Selena, y traía también «Como una flor», de la misma cantante. Según cuenta ella misma, empezó a los trece años como corista de un grupo familiar y luego cantó en orquestas locales de merengue y bachata; su sencillo «Ya no vives en mí» la llevó de gira por Estados Unidos y el Caribe, y tras cerca de cuatro años dejó los escenarios para atender su vida privada. Volvió en 2019 como Yammy.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sencillos y colaboradores","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Desde entonces mezcla colaboraciones y toques urbanos y tropicales con su bachata. Entre sus sencillos figuran «Mala», «Te Superé», «Fuiste un Error», «La Gran Señora», «Tu Dama de Hierro» (2023), «Brindo X Mi Ex» (2024) y «Te Duele Verme Bien» (2025), este último escrito con Eddie Espinal. «El Gallo», grabado con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"550df3b5-6488-4aec-a476-a5d28d52ceea","displayText":"Bulin 47","occurrenceId":"57de74f3-7012-46af-b7b8-31d5fe10900d"}},{"text":", pasa de 1,4 millones de vistas en YouTube. Nombra entre sus colaboradores a ","type":"text"},{"type":"artistReference","attrs":{"artistId":"aec32df5-cc5a-43c2-ac33-02bc8caa1cf5","displayText":"Joe Veras","occurrenceId":"8b666438-d6af-4970-a964-4366883706c4"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"6302aca6-2203-456f-ad96-6bd2f26ee9b3","displayText":"Luis Miguel del Amargue","occurrenceId":"88893a0b-c475-466e-ab23-1e937fe6233b"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0b2e1a39-b265-42d6-95d5-85ad930eee84","displayText":"El Cherry Scom","occurrenceId":"eb199573-c018-4130-bacb-a816616966be"}},{"text":", y ha empezado a escribir sus propias canciones con productores y compositores como ","type":"text"},{"type":"artistReference","attrs":{"artistId":"5cbc8f2b-cb68-4ebd-8006-6837be54bbe4","displayText":"Leo RD","occurrenceId":"482ccb38-35d3-4b73-86b4-a67f873265d6"}},{"text":" y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"350e5535-5229-4d49-903e-a5de047e7723","displayText":"Cromo X","occurrenceId":"ce352c78-280c-4b4f-af13-67575039bda5"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"«Reina de Corazones»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su canción «Papi» es el segundo tema de «Reina de Corazones», tercer volumen de la serie de compilados «Bchta Rising» de «BCHTA Records», publicado el 5 de marzo de 2026 con otros artistas de bachata, entre ellos ","type":"text"},{"type":"artistReference","attrs":{"artistId":"eb79ffea-c981-4328-9d60-028caa180608","displayText":"Lady Laura","occurrenceId":"a767b92f-de08-43d2-ba44-c72ed9553caf"}},{"text":".","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Sigue publicando sencillos y presentándose en Estados Unidos, y en septiembre de 2025 concedió una larga entrevista al canal de YouTube Bacharlando.","type":"text"}]}]}'::jsonb, 'published', id, 2 FROM artists WHERE slug = 'yammy';
UPDATE artists SET bio_en = 'Yammy —born Carmen Jamilka Peña Vargas in Yamasá— is a Dominican bachata singer and songwriter based in New York. She first recorded as Yami Bonetti and came back in 2019 under the name Yammy.

**Two stage names**

In June 2010 Diario Libre, drawing on a profile in the Miami paper El Nuevo Herald, introduced Yami Bonetti as a nineteen-year-old who had left «Las Caribeñas», where she stood in the second row of the chorus, because she no longer wanted to sing behind the lead voices. Her debut album opened with «No me queda más», a bachata take on a Selena song, and also carried Selena’s «Como una flor». By her own account she began at thirteen as a backing singer in a family group and later sang in local merengue and bachata bands; her single «Ya no vives en mí» took her on tours of the United States and the Caribbean, and after roughly four years she left the stage to concentrate on her private life. She returned in 2019 as Yammy.

**Singles and collaborators**

Since then she has blended collaborations and urban and tropical touches into her bachata. Her singles include «Mala», «Te Superé», «Fuiste un Error», «La Gran Señora», «Tu Dama de Hierro» (2023), «Brindo X Mi Ex» (2024) and «Te Duele Verme Bien» (2025), the last written with Eddie Espinal. «El Gallo», recorded with Bulin 47, has passed 1.4 million views on YouTube. She names Joe Veras, Luis Miguel del Amargue and El Cherry Scom among her collaborators, and has begun writing her own songs with producers and songwriters such as Leo RD and Cromo X.

**«Reina de Corazones»**

Her song «Papi» is the second track on «Reina de Corazones», the third volume of the «Bchta Rising» compilation series from «BCHTA Records», released on 5 March 2026 with a group of other bachata artists that includes Lady Laura.

**Legacy**

She keeps releasing singles and performing in the United States, and in September 2025 gave a long interview to the YouTube channel Bacharlando.', bio_es = 'Yammy —nacida Carmen Jamilka Peña Vargas en Yamasá— es cantante y compositora dominicana de bachata radicada en Nueva York. Grabó primero como Yami Bonetti y regresó en 2019 con el nombre de Yammy.

